<template>
  <v-dialog persistent :value="open" max-width="500px">
    <v-card>
      <v-card-title>
        Conectar dispositivo serial
      </v-card-title>
      <v-card-text>
        <div class="d-flex flex-column align-center py-4">
          <div v-if="isConnected" class="mb-4">
            <v-chip color="success" large>
              <v-icon left>mdi-check-circle</v-icon>
              Dispositivo conectado
            </v-chip>
          </div>
          
          <p v-if="!isConnected" class="mb-4 text-center">
            Haz clic en el botón para seleccionar el dispositivo serial desde tu navegador
          </p>
          
          <v-btn 
            v-if="!isConnected"
            color="primary" 
            large 
            @click="connect()"
          >
            <v-icon left>mdi-usb</v-icon>
            Seleccionar dispositivo
          </v-btn>
          
          <div v-if="receivedData" class="mt-4 pa-3" style="max-width: 100%; background: #f5f5f5; border-radius: 4px;">
            <p class="text-subtitle-2 mb-2">Datos recibidos:</p>
            <p class="text-body-2" style="word-break: break-word; max-height: 200px; overflow-y: auto;">
              {{ receivedData }}
            </p>
          </div>
        </div>
      </v-card-text>
      <v-card-actions>
        <v-btn color="primary" text @click="closeScreen()">
          Cerrar
        </v-btn>
        <v-spacer />
        <v-btn 
          v-if="isConnected" 
          color="error" 
          text 
          @click="disconnect()"
        >
          Desconectar
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>
<script>
import { mapState } from 'vuex';

export default {
  data() {
    return {
      port: null,
      receivedData: '',
      reader: null,
      inputDone: null,
      outputDone: null,
      inputStream: null,
      outputStream: null
    };
  },
  props: {
    open: Boolean,
    handleClose: Function
  },
  computed: {
    ...mapState('CardReader', {
      isConnected: state => state.connected,
      portName: state => state.portName
    })
  },
  watch: {
    // Sincronizar cuando se abre el modal
    open(newVal) {
      if (newVal) {
        // Si el store dice que está conectado pero no tenemos port local, hay inconsistencia
        if (this.isConnected && !this.port) {
          console.log('Modal abierto: dispositivo conectado externamente');
        } else if (!this.isConnected && this.port) {
          // Si tenemos port local pero el store dice desconectado, limpiar
          console.log('Modal abierto: limpiando estado inconsistente');
          this.cleanupLocalState();
        }
      }
    }
  },
  methods: {
    async connect() {
      if ('serial' in navigator) {
        try {
          // Esto abre el selector nativo del navegador (Chrome/Brave)
          this.port = await navigator.serial.requestPort();
          await this.port.open({ baudRate: 115200 });
          
          // Notificar al store que se conectó
          if (this.$store && this.$store.dispatch) {
            this.$store.dispatch('CardReader/onConnect', this.port.getInfo());
          }
          
          // Escuchar eventos de desconexión del puerto
          this.port.addEventListener('disconnect', () => {
            console.log('Dispositivo desconectado por evento del puerto');
            this.handleDisconnectEvent();
          });
          
          this.readData();
        } catch (error) {
          console.error('Error al conectar:', error);
          if (error.name !== 'NotFoundError') {
            // NotFoundError significa que el usuario canceló, no mostrar alerta
            this.$store.dispatch("Session/notify", {
              message: "Error al conectar el lector: " + error.message,
              color: "error",
            });
          }
        }
      } else {
        this.$store.dispatch("Session/notify", {
          message: "La Web Serial API no es compatible con este navegador (usa Chrome o Edge)",
          color: "error",
        });
      }
    },
    async readData() {
      this.inputStream = this.port.readable;
      const decoder = new TextDecoderStream();
      this.inputDone = this.inputStream.pipeTo(decoder.writable);
      this.reader = decoder.readable.getReader();

      try {
        while (true) {
          const { value, done } = await this.reader.read();
          if (done) {
            break;
          }
          this.receivedData += value;
          console.log('Datos recibidos:', value);
        }
      } catch (error) {
        console.error('Error al leer datos:', error);
      } finally {
        this.reader.releaseLock();
      }
    },
    async sendData(data = 'Hola dispositivo serial') {
      if (!this.port) {
        console.error('No hay puerto conectado');
        return;
      }
      
      try {
        const encoder = new TextEncoderStream();
        this.outputDone = encoder.readable.pipeTo(this.port.writable);
        const writer = encoder.writable.getWriter();

        await writer.write(data);
        writer.releaseLock();
        console.log('Datos enviados:', data);
      } catch (error) {
        console.error('Error al escribir datos:', error);
      }
    },
    async disconnect() {
      try {
        if (this.reader) {
          await this.reader.cancel();
          await this.inputDone.catch(() => {});
          this.reader = null;
          this.inputDone = null;
        }
        if (this.outputStream) {
          await this.outputStream.getWriter().close();
          await this.outputDone;
          this.outputStream = null;
          this.outputDone = null;
        }
        if (this.port) {
          await this.port.close();
          this.port = null;
        }
        
        this.receivedData = '';
        
        // Notificar al store que se desconectó
        if (this.$store && this.$store.dispatch) {
          this.$store.dispatch('CardReader/onDisconnect');
        }
        
        console.log('Dispositivo desconectado');
      } catch (error) {
        console.error('Error al desconectar:', error);
      }
    },
    handleDisconnectEvent() {
      // Método para manejar desconexiones automáticas
      this.cleanupLocalState();
      if (this.$store && this.$store.dispatch) {
        this.$store.dispatch('CardReader/onDisconnect');
      }
    },
    cleanupLocalState() {
      // Limpiar estado local sin cerrar el puerto (ya está cerrado)
      this.port = null;
      this.reader = null;
      this.inputDone = null;
      this.outputDone = null;
      this.inputStream = null;
      this.outputStream = null;
      this.receivedData = '';
    },
    closeScreen() {
      this.handleClose();
    }
  },
  beforeDestroy() {
    if (this.isConnected) {
      this.disconnect();
    }
  }
};
</script>
<style scoped>
.v-input__control {
  height: 35px !important;
}
</style>
