import io from "socket.io-client";
import { store } from "./index";

// Singleton: un solo socket para toda la app. Antes cada llamada al export
// default podía crear un socket nuevo sin listeners y las respuestas del
// server se perdían.
let socket = null;
let was_connected_once = false;
const pending_emits = [];

// Emite si hay socket; si todavía no se resolvió el host, encola y se envía
// al conectar (evita la carrera Dashboard-monta-antes-que-App-resuelva-host)
export function emitToServer(event, payload) {
  if (socket) socket.emit(event, payload);
  else pending_emits.push([event, payload]);
}

export function connectToSocket() {
  if (socket) return socket;
  socket = io(store.state.Session.BASE_URL);

  // Eventos nativos en vez del polling de 5s: el banner de conexión
  // reacciona al instante y al reconectar se re-sincroniza el estado
  socket.on("connect", () => {
    store.dispatch("Session/connected");
    socket.emit("desk_manager_connected");
    store
      .dispatch("Session/bootstrap", was_connected_once)
      .catch((e) => console.error("bootstrap tras conexión:", e));
    was_connected_once = true;
  });

  socket.on("disconnect", () => {
    store.dispatch("Session/disconnected");
  });

  socket.on("connectedLines", (msg) => {
    store.dispatch("Lines/setConnectedLines", msg.connectedLines);
  });

  socket.on("lineConnected", (msg) => {
    store.dispatch("Lines/connectedLine", msg);
  });

  socket.on("lineDisconnected", (msg) => {
    store.dispatch("Lines/disconnectedLine", msg);
  });

  socket.on("sale-commited", (msg) => {
    store.dispatch("Lines/newSale", msg.data);
    store.dispatch("Sales/addSale", msg.doc);
  });

  pending_emits.splice(0).forEach(([event, payload]) => {
    socket.emit(event, payload);
  });

  return socket;
}

export default function () {
  return socket;
}
