let serialPort = null;
let reader = null;
let writer = null;
let inputDone = null;
let outputDone = null;
let callbackMap = [];
let mainOptions = null;
let isReading = false;

// Función para verificar compatibilidad del navegador
function checkBrowserCompatibility() {
  // Detectar Chrome y Edge (basado en Chromium)
  const isChrome =
    !!window.chrome && (!!window.chrome.webstore || !!window.chrome.runtime);
  const isEdge = navigator.userAgent.includes("Edg/");

  // if (!isChrome && !isEdge) {
  //   console.error("Navegador no compatible. Se requiere Chrome o Edge.");
  //   return false;
  // }

  if (!("serial" in navigator)) {
    console.error(
      "Web Serial API no disponible. Requiere Chrome/Edge 89+ en HTTPS o localhost."
    );
    return false;
  }

  return true;
}

export async function portList() {
  if (!checkBrowserCompatibility()) return [];

  try {
    const ports = await navigator.serial.getPorts();
    return ports.map((port) => ({
      path: port.getInfo().usbVendorId
        ? `VendorID: ${port.getInfo().usbVendorId}`
        : port.path || "Unknown port",
    }));
  } catch (error) {
    console.error("Error al listar puertos:", error);
    return [];
  }
}

// Conexión iniciada por el usuario (requestPort exige un gesto del usuario)
export async function connectPort(store) {
  if (!checkBrowserCompatibility()) {
    if (store && store.dispatch) {
      store.dispatch("CardReader/onDisconnect");
    }
    return false;
  }

  try {
    const port = await navigator.serial.requestPort();
    return await openPort(port, store);
  } catch (error) {
    console.error("Error al conectar:", error);
    if (store && store.dispatch) {
      store.dispatch("CardReader/onDisconnect");
    }
    cleanupConnection();
    return false;
  }
}

// Reconexión automática (al cargar la app): usa los puertos ya autorizados,
// que no requieren gesto del usuario. requestPort() en un mounted() falla
// siempre porque el navegador exige un gesto.
export async function reconnectGrantedPort(store) {
  if (!checkBrowserCompatibility()) return false;
  try {
    const ports = await navigator.serial.getPorts();
    if (ports.length === 0) return false;
    return await openPort(ports[0], store);
  } catch (error) {
    console.error("Error al reconectar puerto autorizado:", error);
    return false;
  }
}

async function openPort(port, store) {
  try {
    serialPort = port;
    await serialPort.open({ baudRate: 115200 });

    // Configurar lectura
    const decoder = new TextDecoderStream();
    inputDone = serialPort.readable.pipeTo(decoder.writable);
    reader = decoder.readable.getReader();

    // Configurar escritura
    const encoder = new TextEncoderStream();
    outputDone = encoder.readable.pipeTo(serialPort.writable);
    writer = encoder.writable.getWriter();

    // Escribir carácter inicial (^ en tu ejemplo original)
    try {
      await writer.write("^");
    } catch (writeError) {
      console.error("Error al enviar carácter inicial:", writeError);
    }

    if (store && store.dispatch) {
      store.dispatch("CardReader/onConnect", serialPort.getInfo());
    }

    // Manejar cierre
    serialPort.addEventListener("disconnect", () => {
      console.log("Puerto desconectado por evento");
      if (store && store.dispatch) {
        store.dispatch("CardReader/onDisconnect");
      }
      cleanupConnection();
    });

    // Leer datos continuamente
    isReading = true;
    readLoop(reader, store);
    return true;
  } catch (error) {
    console.error("Error al abrir puerto:", error);
    if (store && store.dispatch) {
      store.dispatch("CardReader/onDisconnect");
    }
    cleanupConnection();
    return false;
  }
}

async function readLoop(reader, store) {
  try {
    while (isReading) {
      const { value, done } = await reader.read();
      if (done) {
        console.log("Lectura completada");
        break;
      }

      const decodedData = value.replace(/(\r\n|\n|\r)/gm, "");
      console.log("Datos recibidos:", decodedData);

      // Ejecutar callbacks suscritos
      if (callbackMap.length > 0) {
        callbackMap.forEach((element) => {
          try {
            element(decodedData);
          } catch (callbackError) {
            console.error("Error en callback:", callbackError);
          }
        });
      } else if (mainOptions) {
        try {
          mainOptions(decodedData, true);
        } catch (mainError) {
          console.error("Error en mainOptions:", mainError);
        }
      }
    }
  } catch (error) {
    if (error.name === "NetworkError" || error.name === "TypeError") {
      console.log("Puerto desconectado durante lectura");
    } else {
      console.error("Error en lectura:", error);
    }
  } finally {
    if (store && store.dispatch) {
      store.dispatch("CardReader/onDisconnect");
    }
    cleanupConnection();
  }
}

export function setMainOptions(callback) {
  mainOptions = callback;
}

export function suscribe(callback) {
  if (!callbackMap.includes(callback)) {
    callbackMap.push(callback);
  }
}

export function unsuscribe(callback) {
  if (callback) {
    callbackMap = callbackMap.filter((cb) => cb !== callback);
  } else {
    callbackMap = [];
  }
}

export async function disconnectPort(store) {
  isReading = false;

  if (reader) {
    try {
      await reader.cancel();
    } catch (error) {
      console.error("Error al cancelar reader:", error);
    }
    reader = null;
  }

  if (inputDone) {
    await inputDone.catch(() => {});
    inputDone = null;
  }

  if (writer) {
    try {
      await writer.close();
    } catch (error) {
      console.error("Error al cerrar writer:", error);
    }
    writer = null;
  }

  if (outputDone) {
    await outputDone.catch(() => {});
    outputDone = null;
  }

  if (serialPort) {
    try {
      await serialPort.close();
    } catch (error) {
      console.error("Error al cerrar puerto:", error);
    }
    serialPort = null;
  }

  if (store && store.dispatch) {
    store.dispatch("CardReader/onDisconnect");
  }

  console.log("Puerto desconectado completamente");
}

// Función auxiliar para limpiar la conexión sin llamar al store
function cleanupConnection() {
  isReading = false;
  reader = null;
  inputDone = null;
  writer = null;
  outputDone = null;
  serialPort = null;
}

export function isConnected() {
  return serialPort !== null && isReading;
}

// Nueva función para escribir datos al puerto serie
export async function writeToPort(data) {
  if (!writer) {
    console.error("No hay conexión activa con el puerto serie");
    return false;
  }

  try {
    await writer.write(data);
    console.log("Datos enviados:", data);
    return true;
  } catch (error) {
    console.error("Error al escribir en el puerto:", error);
    return false;
  }
}
